"""Additional original catalogue categories; invoked by build_catalog.py."""
def extend(source,item,add):
 source('m50ii','Canon EOS M50 Mark II specifications','https://cam.start.canon/uk/C007/manual/html/UG-11_Reference_0090.html','Canon','EOS M50 Mark II, EF-M mount; use appropriate lenses, not a similarly named DSLR.')
 source('z50','Nikon Z 50 online manual','https://onlinemanual.nikonimglib.com/z50/en/','Nikon','Original Z 50 model, not Z50II; camera operation and supported accessories.')
 source('xt30ii','FUJIFILM X-T30 II specifications','https://fujifilm-dsc.com/en/manual/x-t30-2/technical_notes/spec/','FUJIFILM','X-T30 II operation/connection reference; not first-generation X-T30.')
 source('zve10','Sony ZV-E10 Help Guide','https://helpguide.sony.net/ilc/2070/v1/en/index.html','Sony','Original ZV-E10, not ZV-E10 II. Lens capabilities vary.')
 cameras=[('Canon','EOS-M50-MARK-II','Canon EOS M50 Mark II','m50ii','EF-M lens mount, vari-angle display and electronic viewfinder'),('Nikon','Z50','Nikon Z 50','z50','Z lens mount, tilting display and electronic viewfinder'),('FUJIFILM','X-T30-II','FUJIFILM X-T30 II','xt30ii','X mount, tilting display and electronic viewfinder'),('Sony','ZV-E10','Sony ZV-E10','zve10','E mount and side-opening display; this model has no electronic viewfinder')]
 for brand,code,name,ref,features in cameras:
  add('cameras',brand,code,name,[
   item('Body and included lens',['Check the body/model label, '+features+'.','Confirm the included lens, battery, charger/cable, cap and any extras against the listing.'],'Agreed model/bundle.','Wrong variant, damaged mount or missing agreed items.','A body-only listing need not include a lens. Exterior labels are not proof of originality.',[ref]),
   item('Focus and saved photographs',['Use a compatible known-good lens and memory card.','Focus on a near then distant subject; take several photographs and review the saved files.'],'Focus and recording work.','Repeated focus errors, corrupt files or unexpected shutdowns.','Lens, card and settings can cause symptoms; retest before blaming the body. No shutter-life guarantee. Canon M50 II autofocus behaviour differs between recording modes. Neutral subjects/light are recommended.',[ref]),
   item('Display, controls and video',['Operate buttons/dials and move the display gently through its normal range.','Record and replay a short video with sound; test the viewfinder if fitted.'],'Responsive controls and stable playback.','Display dropouts, dead buttons or distorted audio.','Do not force a hinge. Short video does not establish long-recording thermal performance.',[ref]),
   item('Visible condition and power',['Inspect grip, battery/card doors and accessible ports; do not touch the sensor or remove parts.','Try the supplied compatible power/charging method according to the manual.'],'Doors latch and power is stable.','Swelling, corrosion, broken door latch or intermittent power.','No sensor cleaning, laser/bright-sun exposure or destructive disassembly. Dust/optical defects need controlled lens/body tests.',[ref])],tools='Compatible lens, empty known-good memory card, charged battery, agreed power accessories and seller permission.')
 source('u2720q','Dell U2720Q user guide','https://dl.dell.com/manuals/all-products/esuprt_electronics_accessories/esuprt_electronics_accessories_monitors/dell-u2720q-monitor_user%27s-guide_en-us.pdf','Dell','U2720Q controls and built-in diagnostics; USB-C use requires a compatible host/cable.')
 source('27ul500','LG 27UL500-W support and manuals','https://www.lg.com/uk/support/product-support/cs-27UL500-W.AWF/','LG','27UL500-W model; regional suffix may differ.')
 source('vg249q','ASUS TUF Gaming VG249Q specifications','https://www.asus.com/uk/displays-desktops/monitors/tuf-gaming/tuf-gaming-vg249q/techspec/','ASUS','Original VG249Q; do not substitute VG249Q1A/Q3A specifications.')
 source('s24r350','Samsung S24R350FHN support','https://www.samsung.com/us/business/support/owners/product/sr24r-series-s24r350fhn/','Samsung','24-inch SR35 family; local regional suffix and supplied adapters may differ.')
 source('gw2480','BenQ GW2480 specifications','https://www.benq.com/en-us/monitor/home/gw2480/spec.html','BenQ','GW2480 connection and speaker configuration, not GW2480T stand options.')
 monitors=[('Dell','U2720Q','Dell UltraSharp U2720Q','u2720q','HDMI, DisplayPort and USB-C video','Use the U2720Q built-in diagnostics following its manual, with video cables disconnected when instructed.'),('LG','27UL500-W','LG 27UL500-W','27ul500','HDMI and DisplayPort video','Use full-screen white, black, red, green and blue images from a known-good computer.'),('ASUS','VG249Q','ASUS TUF Gaming VG249Q','vg249q','HDMI and DisplayPort video','Select the intended supported refresh rate on a compatible computer; inspect moving content for dropouts.'),('Samsung','S24R350','Samsung S24R350 24-inch','s24r350','HDMI and VGA video','Use plain colours; compare the monitor label with the advertised regional model.'),('BenQ','GW2480','BenQ GW2480','gw2480','HDMI, DisplayPort and VGA video','Play a short audio sample through the selected supported input and check the built-in speakers.')]
 for brand,code,name,ref,ports,extra in monitors:
  add('monitors',brand,code,name,[
   item('Model, stand and screen surface',['Compare the rear model label and supplied stand/power accessories with the listing.','Inspect the unpowered screen under indirect light without pressing it.'],'Correct model and disclosed wear.','Cracks, pressure marks or missing stand fixings.','A VESA mount may replace the original stand only by agreement. Do not remove coatings or press the panel.',[ref]),
   item('Display and repeatable defects',[extra,'Look at normal distance for persistent spots, lines, discolouration and flicker.'],'Image is stable and meets your agreed defect tolerance.','Repeatable lines, bright/dark spots or image loss.','No invented zero-defect warranty. Ambient light and IPS viewing angle affect black appearance; a phone photo is not a calibration test.',[ref]),
   item('Inputs and controls',['Test '+ports+' where equipment is available.','Switch inputs in the on-screen menu; record every connector not tested.'],'Agreed inputs work.','Loose connector, repeated loss of signal or dead controls.','Known-good host/cables are essential. Unsupported resolution/refresh rate is not proof of damage.',[ref]),
   item('Stable power and safe setup',['Observe normal use for several minutes, including a power cycle.','Check stand stability, vents and cable condition without opening the monitor.'],'Stable operation and safe support.','Shutdowns, damaged power cable or unstable stand.','Short observation cannot establish backlight life or colour accuracy. Disconnect unsafe power accessories.',[ref])],tools='Known-good computer, supported video/power cables, plain-colour test images and agreed adapters.')
 source('ps5-1200','PS5 CFI-12XXA quick start guide','https://www.playstation.com/content/dam/global_pdc/en-gb/corporate/support/manuals/ps5-docs/1200a/CFI-12XXA_PS5_Quick_Start_Guide%24en-gb.pdf','Sony Interactive Entertainment','Original CFI-1200 disc model; base arrangement differs from Slim/Pro.')
 source('xbox-compare','Compare Xbox Series consoles','https://www.xbox.com/en-US/consoles/compare/','Microsoft Xbox','1TB Carbon Black disc Series X and 512GB Robot White all-digital Series S; not every later colour/storage variant.')
 source('xbox-start','Xbox consoles getting started','https://www.xbox.com/en-US/consoles/getting-started','Microsoft Xbox','Setup and storage context. Seller-account purchases are not transferred by this guide.')
 source('switch-oled','Nintendo Switch OLED overview and FAQ','https://en-americas-support.nintendo.com/app/answers/detail/a_id/55834/~/nintendo-switch-%E2%80%93oled-model-overview-and-faq','Nintendo','HEG-001 OLED and HAC-001(-01) comparison; different docks and display technology.')
 source('switch-support','Nintendo Switch support overview','https://www.nintendo.com/ph/support/switch/modal/outline.html?width=960','Nintendo','Switch family operation; use original matching power/dock equipment.')
 for brand,code,name,ref,optical in [('Sony','CFI-1200A','PlayStation 5 CFI-1200 disc edition','ps5-1200',True),('Microsoft','XBOX-SERIES-X-1TB-DISC','Xbox Series X 1TB Carbon Black','xbox-compare',True),('Microsoft','XBOX-SERIES-S-512GB','Xbox Series S 512GB Robot White','xbox-compare',False)]:
  add('consoles',brand,code,name,[
   item('Exact edition and bundle',['Check console model/storage, controller and power/HDMI accessories against the listing.','Confirm '+('the physical disc drive is present.' if optical else 'this is the all-digital 512GB version, without a disc drive.')],'Agreed edition and bundle.','Wrong storage/edition or damaged connectors.','Usable storage is below nominal capacity; bundled digital purchases may be account-bound.',[ref]),
   item('Real gameplay and controller',['Connect to a known-good display; start an available game with permission.','Test sticks, triggers, buttons and wireless connection in gameplay.'],'Stable picture and responsive controls.','Uncommanded movement, failed buttons, artifacts or crashes.','Game settings/deadzones affect stick response. Do not call any firmware reset a repair.',[ref]),
   item('Disc or digital access',(['Insert a clean compatible game disc; launch and eject it.','Keep the console in the orientation specified by its manual.'] if optical else ['Launch an available digital game; confirm you can use your own account/network with permission.','Do not treat the seller\'s installed games as transferred ownership.']),'Agreed media works.','Read/eject errors or unusable agreed access.','One game cannot test all media or guarantee future online access. Never accept account-password sharing as a substitute for ownership.',[ref]),
   item('Power, network and handover',['Observe normal gameplay with clear ventilation; inspect the casing and power cable.','Ask seller to resolve parental/owner restrictions; verify agreed clean setup without deleting data yourself.'],'Stable use and usable setup.','Repeated shutdowns, blocked setup or undisclosed restrictions.','No console opening or blocked-vent stress tests. Online service availability and account status are separate from hardware condition.',['xbox-start' if brand=='Microsoft' else ref])],tools='Known-good display/HDMI, compatible power cable, game, controller and seller permission.')
 for code,name,oled in [('HEG-001','Nintendo Switch OLED',True),('HAC-001-01','Nintendo Switch revised model',False)]:
  add('consoles','Nintendo',code,name,[
   item('Model and supplied dock',['Compare the console label with '+('HEG-001 OLED' if oled else 'HAC-001(-01) revised Switch')+'.','Confirm Joy-Con, compatible dock, AC adapter and HDMI cable included as agreed.'],'Correct model and agreed accessories.','Wrong version or unsafe/missing power accessories.','OLED and standard docks differ; a swapped compatible dock should be disclosed.',['switch-oled']),
   item('Screen and touch',['View light/dark images and a game in handheld mode.','Test touch in supported menus and inspect the screen edges.'],'Stable display and responsive touch.','Cracks, dead areas or persistent marks.','OLED burn-in and LCD viewing effects differ; no invented pixel allowance.',['switch-oled']),
   item('Joy-Con and cartridge',['Use system controller stick calibration to observe centring without changing settings.','Test buttons, rail attachment and a known-good game card with permission.'],'Sticks centre and controls/card work.','Drift, disconnects or card-read errors.','Do not recalibrate to conceal a defect. Settings/game deadzones may affect symptoms.',['switch-support']),
   item('TV mode, charging and handover',['Test TV output using compatible dock, adapter and HDMI cable; then check handheld charging.','Ask seller to resolve account/parental restrictions before agreed setup.'],'Both modes work; setup is usable.','No TV output, unstable charge or locked setup.','Retest with known-good accessories. Seller\'s digital software is not automatically transferred.',['switch-support'])],tools='Compatible dock/AC adapter, HDMI display, game card and seller permission.')
